const contactId = inputData.contactId;
const response = await customRequest.get(
  `https://services.leadconnectorhq.com/contacts/${contactId}`,
  {
    headers: {
      'Authorization': 'Bearer pit-06383926-0745-4053-898a-f18b22eee3e8',
      'Version': '2021-07-28',
      'Accept': 'application/json'
    }
  }
);
const contact = response.data.contact;
const d = new Date(contact.dateAdded);
const cstOffset = -6 * 60;
const cstTime = new Date(d.getTime() + cstOffset * 60 * 1000);
const month = String(cstTime.getMonth() + 1).padStart(2, '0');
const day = String(cstTime.getDate()).padStart(2, '0');
const year = cstTime.getFullYear();
const formattedDate = `${month}/${day}/${year}`;
output = {
  dateAdded: contact.dateAdded,
  dateAddedFormatted: formattedDate,
  contactId: contact.id
};
